  function element(tag,classes,text) { const n=document.createElement(tag); if(classes)n.className=classes; if(text!==undefined)n.textContent=String(text);return n; }
  function stable(value) {
    if(value===null || typeof value!=='object') return JSON.stringify(value);
    if(Array.isArray(value)) return '['+value.map(stable).join(',')+']';
    return '{'+Object.keys(value).sort().map(k=>JSON.stringify(k)+':'+stable(value[k])).join(',')+'}';
  }
  async function digest(value) {
    const data=new TextEncoder().encode(stable(value));
    if(data.byteLength>LIMITS.fileBytes)throw new Error('Record exceeds the 4 MiB limit.');
    const result=await crypto.subtle.digest('SHA-256',data);
    return Array.from(new Uint8Array(result),v=>v.toString(16).padStart(2,'0')).join('');
  }
