    const table=$('m-table');table.replaceChildren();const head=element('tr');['Label',complex?(d.representation==='samples'?'Source coordinate':'Original sample coordinate (metadata)'):'Field code',complex?'Raw value':'Field element'].forEach(x=>head.append(element('th',null,x)));table.append(head);const root=$('m-bars');root.replaceChildren();root.hidden=!complex;const maximum=complex?Math.max(...d.values.map(v=>Math.hypot(v.re,v.im)),Number.MIN_VALUE):1;
