  async function loadReappliedModel(){if(state.busy)return;if(state.records.length>=LIMITS.records){log('gfm.load','Ledger is full; export before loading a recorded model.',false);return;}setBusy(true);try{const result=await perform('gfm.reapply');if(result.ok){await perform('gfm.record Reapplied GFM mechanics data');showView('terminal');}}finally{setBusy(false);}}
