  function validateSmallSnapshot(snap){if(!snap || !snap.model || snap.model.schema!=='RUSSL-finite-field-model/1')throw new Error('Unsupported finite-field snapshot.');const m=snap.model;const f=E.field(m.field && m.field.id);if(stable(m.field)!==stable(E.fields[f.id]))throw new Error('Field metadata differs from the registered model.');if(m.amplitudes!=='complex floating point' || m.fourierSign!=='+2pi i' || m.normalization!=='1/sqrt(q)' || m.character!=='exp(2pi i Tr(x)/p)' || m.labelEncoding!=='integer = sum(c_i * p^i), polynomial coefficients low first' || m.tolerance!==E.tolerance)throw new Error('Snapshot conventions differ from the active engine.');E.fourier(f,snap.state);if(Math.abs(E.norm(snap.state)**2-1)>E.tolerance)throw new Error('Imported state is not normalized.');if(!Number.isSafeInteger(snap.operations)||snap.operations<0||snap.operations>1e9)throw new Error('Invalid operation count.');if(typeof snap.description!=='string'||snap.description.length>200)throw new Error('Invalid state description.');validatePreparation(snap.preparation,f);}
