  async function importFile(file){if(state.busy)return;if(!file||file.size>LIMITS.fileBytes){log('session.import','Use a session JSON file no larger than 4 MiB.',false);return;}setBusy(true);try{const data=await validatePacket(JSON.parse(await file.text()));const context=data.horizonSimulation,newScenario=context?S.scenario(context.parameters):clone(HD.scenario),newProbe=context?context.probe:"exterior";const newMechanics=data.mechanics?GM.validate(clone(data.mechanics)):GM.profile('gf9','pendulum',{g:9.81,length:1,maxAngle:.2});const snap=data.snapshot;state.mechanics=newMechanics;state.referenceMath=false;state.horizon=newScenario;state.probe=newProbe;state.fieldId=snap.model.field.id;state.vector=clone(snap.state);state.preparation=snap.preparation?clone(snap.preparation):null;state.description=snap.description;state.operations=snap.operations;state.audit=E.audit(activeField(),state.vector);state.records=clone(data.records);state.history=clone(data.commandProvenance||[]);state.returns=clone(data.returns||[]);state.selectedReturn=null;renderState();renderMechanics();renderHorizon();renderLedger();renderReturn();log('session.import',`Verified ${state.records.length} record envelopes; imported as inert data. GF80 records await explicit replay.`);$('footer-status').textContent='Session imported · export to preserve subsequent changes';}catch(error){log('session.import',error.message||String(error),false);}finally{setBusy(false);$('session-file').value='';}}
